def brute_force(n: int) -> int:
    # Try both moves at every odd number (exponential-shaped recursion tree).
    if n <= 1:
        return 0
    if n % 2 == 0:
        return 1 + brute_force(n // 2)
    return 1 + min(brute_force(n + 1), brute_force(n - 1))

