class Solution:
    def integerReplacement(self, n: int) -> int:
        steps = 0
        while n > 1:
            if n & 1 == 0:
                n >>= 1
            elif n == 3 or n & 3 == 1:  # ...01: subtract; 3 is the lone exception
                n -= 1
            else:                       # ...11: add, carry clears the run of 1s
                n += 1
            steps += 1
        return steps

