def brute_force(s: str) -> int:
    # ways(i) = decodings of s[i:]; tries a 1-digit and a 2-digit code: exponential.
    def ways(i: int) -> int:
        if i == len(s):
            return 1
        if s[i] == "0":
            return 0
        total = ways(i + 1)
        if i + 1 < len(s) and int(s[i:i + 2]) <= 26:
            total += ways(i + 2)
        return total

    return ways(0)

