class Solution:
    def numDecodings(self, s: str) -> int:
        prev2, prev1 = 1, 1 if s[0] != "0" else 0  # dp[i-2], dp[i-1]
        for i in range(2, len(s) + 1):
            cur = prev1 if s[i - 1] != "0" else 0
            if 10 <= int(s[i - 2:i]) <= 26:
                cur += prev2
            prev2, prev1 = prev1, cur
        return prev1

