def brute_force(nums: List[int]) -> int:
    # Take-or-skip recursion over every subsequence: O(2^n).
    def best(i: int, prev: int) -> int:
        if i == len(nums):
            return 0
        skip = best(i + 1, prev)
        if prev == -1 or nums[i] > nums[prev]:
            return max(skip, 1 + best(i + 1, i))
        return skip

    return best(0, -1)

