class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        tails = []  # tails[L-1] = smallest tail of an increasing run of length L
        for x in nums:
            i = bisect_left(tails, x)  # first tail >= x (strictly increasing)
            if i == len(tails):
                tails.append(x)
            else:
                tails[i] = x
        return len(tails)

