def brute_force(cost: List[int]) -> int:
    # f(i) = cost from stair i to the top, trying both jumps: exponential.
    def f(i: int) -> int:
        if i >= len(cost):
            return 0
        return cost[i] + min(f(i + 1), f(i + 2))

    return min(f(0), f(1))

