class Solution:
    def canPartition(self, nums: List[int]) -> bool:
        total = sum(nums)
        if total % 2:
            return False
        reach = 1  # bit s set <=> some subset sums to s
        for x in nums:
            reach |= reach << x
        return (reach >> (total // 2)) & 1 == 1

