def brute_force(coins: List[int], amount: int) -> int:
    # Try every coin as the next coin, recursively: exponential.
    def f(a: int) -> float:
        if a == 0:
            return 0
        return min((1 + f(a - c) for c in coins if c <= a), default=float("inf"))

    best = f(amount)
    return -1 if best == float("inf") else best

