def brute_force(nums: List[int], target: int) -> int:
    # Try '+' and '-' on every number: O(2^n).
    def ways(i: int, s: int) -> int:
        if i == len(nums):
            return 1 if s == target else 0
        return ways(i + 1, s + nums[i]) + ways(i + 1, s - nums[i])

    return ways(0, 0)

