class Solution:
    def findTargetSumWays(self, nums: List[int], target: int) -> int:
        counts = {0: 1}  # running sum -> number of sign patterns reaching it
        for x in nums:
            nxt = defaultdict(int)
            for s, c in counts.items():
                nxt[s + x] += c
                nxt[s - x] += c
            counts = nxt
        return counts.get(target, 0)
